#ifndef GEMM_BF16_VAR_MNK_KERNEL_H
#define GEMM_BF16_VAR_MNK_KERNEL_H

#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <hip/hip_bfloat16.h>
#include <rocblas/rocblas.h>
#include <cstdint>

#define HIP_CHECK(cmd)                                                                    \
  do {                                                                                    \
    hipError_t e = (cmd);                                                                 \
    if (e != hipSuccess) {                                                                \
      throw std::runtime_error(std::string("HIP error: ") + hipGetErrorString(e));       \
    }                                                                                     \
  } while (0)

#define ROCBLAS_CHECK(cmd)                                                                \
  do {                                                                                    \
    rocblas_status s = (cmd);                                                             \
    if (s != rocblas_status_success) {                                                    \
      throw std::runtime_error("rocBLAS error code: " + std::to_string((int)s));         \
    }                                                                                     \
  } while (0)

void gemm_bf16_var_mnk_launcher(
    const hip_bfloat16* A,
    const hip_bfloat16* B,
    hip_bfloat16* C,
    int64_t M,
    int64_t N,
    int64_t K,
    hipStream_t stream);

#endif

#include "kernel.h"
#include <stdexcept>

// Fallback kernel (kept for completeness/debug); MI300X fast path uses rocBLAS MFMA.
__global__ void gemm_bf16_fallback_kernel(
    const hip_bfloat16* __restrict__ A,
    const hip_bfloat16* __restrict__ B,
    hip_bfloat16* __restrict__ C,
    int M, int N, int K) {
  int row = blockIdx.y * blockDim.y + threadIdx.y;
  int col = blockIdx.x * blockDim.x + threadIdx.x;
  if (row >= M || col >= N) return;

  float acc = 0.0f;
  for (int k = 0; k < K; ++k) {
    float a = __bfloat162float(A[row * K + k]);
    float b = __bfloat162float(B[col * K + k]); // B is [N, K], matmul uses B^T
    acc += a * b;
  }
  C[row * N + col] = __float2bfloat16(acc);
}

void gemm_bf16_var_mnk_launcher(
    const hip_bfloat16* A,
    const hip_bfloat16* B,
    hip_bfloat16* C,
    int64_t M,
    int64_t N,
    int64_t K,
    hipStream_t stream) {
  if (M <= 0 || N <= 0 || K <= 0) {
    throw std::runtime_error("M, N, K must be > 0");
  }

  // rocBLAS on MI300X uses MFMA tensor cores for BF16 GEMM paths.
  rocblas_handle handle;
  ROCBLAS_CHECK(rocblas_create_handle(&handle));
  ROCBLAS_CHECK(rocblas_set_stream(handle, stream));

  const float alpha = 1.0f;
  const float beta = 0.0f;

  // We need: C[M, N] = A[M, K] * B[N, K]^T
  // In rocBLAS column-major API, compute C_col(N,M) = op(B_col(N,K)) * op(A_col(K,M))
  // with op(B)=N, op(A)=N gives equivalent row-major math above.
  ROCBLAS_CHECK(rocblas_gemm_ex(
      handle,
      rocblas_operation_none,  // op(B_col)
      rocblas_operation_none,  // op(A_col)
      static_cast<int>(N),     // m
      static_cast<int>(M),     // n
      static_cast<int>(K),     // k
      &alpha,
      B, rocblas_datatype_bf16_r, static_cast<int>(N), // A in API (B logical)
      A, rocblas_datatype_bf16_r, static_cast<int>(K), // B in API (A logical)
      &beta,
      C, rocblas_datatype_bf16_r, static_cast<int>(N), // C_col
      C, rocblas_datatype_bf16_r, static_cast<int>(N),
      rocblas_datatype_f32_r,
      rocblas_gemm_algo_standard,
      0,
      0));

  ROCBLAS_CHECK(rocblas_destroy_handle(handle));
  HIP_CHECK(hipGetLastError());
}

#include <torch/extension.h>
#include <pybind11/pybind11.h>
#include <ATen/cuda/CUDAContext.h>
#include <stdexcept>
#include "kernel.h"

namespace py = pybind11;

static void validate_inputs(const torch::Tensor& A, const torch::Tensor& B) {
  if (A.dim() != 2 || B.dim() != 2) {
    throw std::runtime_error("A and B must be 2D tensors");
  }
  if (A.scalar_type() != torch::kBFloat16 || B.scalar_type() != torch::kBFloat16) {
    throw std::runtime_error("A and B must be bfloat16");
  }
  if (A.size(1) != B.size(1)) {
    throw std::runtime_error("K dimension mismatch: A.shape[1] must equal B.shape[1]");
  }
  if (A.size(0) <= 0 || B.size(0) <= 0 || A.size(1) <= 0) {
    throw std::runtime_error("M, N, K must be > 0");
  }
}

torch::Tensor run(torch::Tensor A, torch::Tensor B) {
  validate_inputs(A, B);

  // Move CPU tensors to GPU, keep GPU tensors on their current device.
  auto A_gpu = A.is_cuda() ? A.contiguous() : A.contiguous().to(torch::kCUDA);
  auto B_gpu = B.is_cuda() ? B.contiguous() : B.contiguous().to(torch::kCUDA);

  auto M = A_gpu.size(0);
  auto K = A_gpu.size(1);
  auto N = B_gpu.size(0);

  auto C_gpu = torch::empty({M, N}, A_gpu.options().dtype(torch::kBFloat16));

  hipStream_t stream = at::cuda::getDefaultCUDAStream(A_gpu.device().index());
  gemm_bf16_var_mnk_launcher(
      reinterpret_cast<const hip_bfloat16*>(A_gpu.data_ptr<at::BFloat16>()),
      reinterpret_cast<const hip_bfloat16*>(B_gpu.data_ptr<at::BFloat16>()),
      reinterpret_cast<hip_bfloat16*>(C_gpu.data_ptr<at::BFloat16>()),
      M, N, K, stream);

  HIP_CHECK(hipStreamSynchronize(stream));
  return C_gpu.cpu();
}

torch::Tensor run_py(py::args args, py::kwargs kwargs) {
  torch::Tensor A, B;

  if (kwargs && kwargs.contains("A") && kwargs.contains("B")) {
    A = kwargs["A"].cast<torch::Tensor>();
    B = kwargs["B"].cast<torch::Tensor>();
  } else if (args.size() >= 2) {
    A = args[0].cast<torch::Tensor>();
    B = args[1].cast<torch::Tensor>();
  } else {
    throw std::runtime_error("run expects (A, B) either as positional args or kwargs");
  }

  return run(A, B);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
  m.def("run", &run_py, "gemm_bf16_var_mnk (HIP/MI300X)");
}
